import { format } from 'prettier';
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
// packageSource flattens the committed client sources into /app/clients for Docker.
// A full checkout keeps their canonical location at the repository root.
const packaged = new URL('../clients/', import.meta.url);
const root = existsSync(packaged) ? packaged : new URL('../../clients/', import.meta.url);
const files = {};
for (const name of readdirSync(root, { recursive: true }).sort()) {
  if (
    !/^(codex\/|claude-code\/|\.agents\/|\.claude-plugin\/)/.test(name) ||
    !/\.(json|md)$/.test(name)
  )
    continue;
  files[name] = readFileSync(new URL(name, root), 'utf8');
}
writeFileSync(
  new URL('../packages/scope/src/client-bundle.ts', import.meta.url),
  await format(
    '// Generated by scripts/build-client-bundle.mjs; edit clients/ instead.\nexport const clientBundle: Record<string, string> = ' +
      JSON.stringify(files, null, 2) +
      ';\n',
    { parser: 'typescript', singleQuote: true, printWidth: 100 },
  ),
);
